-function matchLocated(ref: ReviewHunkRef, liveByKey: Map<string, LiveHunk>): LiveHunk[] {
+function refMatches(
+  ref: FileHunkRef | LocatedHunkRef,
+  liveByKey: Map<string, LiveHunk>,
